// This file was generated by Prisma, and assumes you have installed the following:
// npm install --save-dev prisma dotenv
import 'dotenv/config';
import { defineConfig } from 'prisma/config';

// DATABASE_PROVIDER 選擇兩軌各自的 schema 產生物與 migrations 目錄（FR-018、FR-020）。
// schema 產生物由 `npm run db:schema`（scripts/build-schema.ts）產出，本檔不得回頭指向
// prisma/base.prisma（那份不含 datasource／generator，無法單獨使用）。
const track = process.env['DATABASE_PROVIDER'] === 'postgresql' ? 'postgres' : 'sqlite';

export default defineConfig({
  schema: `prisma/generated/schema.${track}.prisma`,
  migrations: {
    path: `prisma/migrations/${track}`,
    seed: 'tsx prisma/seed.ts',
  },
  datasource: {
    url: process.env['DATABASE_URL'],
    // PostgreSQL 軌產生 migration 需要 shadow database（`prisma migrate dev` 與
    // `migrate diff --from-migrations` 皆然）。Prisma 7 已移除 `--shadow-database-url`
    // 旗標，只能由本檔提供 —— 未設定時 postgres 軌無法產生 migration，
    // 而錯誤訊息不會指向這裡（tasks.md 交接事項 A）。
    // 本機 `docker-compose.yml` 已備妥 `novelsite_shadow` 資料庫。
    // SQLite 軌不需要（Prisma 自行建立暫時檔），故只在 postgres 軌帶入。
    shadowDatabaseUrl:
      track === 'postgres'
        ? (process.env['SHADOW_DATABASE_URL'] ??
          'postgresql://novelsite:novelsite@localhost:5432/novelsite_shadow')
        : undefined,
  },
});
